  _out += "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>MAR SUM V2 — Cancel WO</title>\n  <style>\n  body { font-family: Arial, sans-serif; margin: 0; padding: 0; background: #f5f5f5; color: #1f2937; }\n  .navbar { background: white; padding: 1rem 2rem; border-bottom: 1px solid #ddd; }\n  .nav-brand { font-weight: 600; font-size: 1.125rem; margin-bottom: 10px; }\n  .nav-menu { display: flex; gap: 0.5rem; flex-wrap: wrap; margin: 10px 0; }\n  .nav-link { padding: 0.5rem 1rem; color: #666; text-decoration: none; border-radius: 6px; display: inline-block; }\n  .nav-link:hover { background: #f0f0f0; }\n  .nav-link.active { background: #fee2e2; color: #b91c1c; }\n  .nav-user { margin-top: 10px; font-size: 0.875rem; color: #666; }\n  .container { max-width: 900px; margin: 0 auto; padding: 1.5rem; }\n  .page-title { font-size: 1.6rem; margin: 0 0 0.4rem; }\n  .page-subtitle { color: #555; margin: 0 0 1rem; line-height: 1.5; font-size: 0.92rem; }\n  .ringkas { display: flex; gap: 8px; flex-wrap: wrap; margin-bottom: 12px; }\n  .ringkas span { background: #fff; border: 1px solid #e5e7eb; border-radius: 999px; padding: 4px 12px; font-size: 0.85rem; }\n  .cari { width: 100%; box-sizing: border-box; padding: 12px 14px; font-size: 1rem; border: 1px solid #d1d5db; border-radius: 10px; margin-bottom: 14px; }\n  .kartu { background: #fff; border: 1px solid #e5e7eb; border-radius: 12px; padding: 14px 16px; margin-bottom: 10px; }\n  .kartu-atas { display: flex; justify-content: space-between; gap: 10px; align-items: flex-start; flex-wrap: wrap; }\n  .no { font-family: ui-monospace, Menlo, Consolas, monospace; font-weight: 700; font-size: 1rem; word-break: break-all; }\n  .lencana { font-size: 0.75rem; font-weight: 700; padding: 3px 10px; border-radius: 999px; white-space: nowrap; }\n  .st-pending_mechanic_work, .st-created { background: #e0f2fe; color: #0369a1; }\n  .st-in_progress { background: #fef3c7; color: #92400e; }\n  .st-pending_transfer { background: #ede9fe; color: #6d28d9; }\n  .st-pending_supervisor { background: #ffedd5; color: #c2410c; }\n  .isi { margin-top: 8px; font-size: 0.9rem; line-height: 1.55; color: #374151; }\n  .isi .lbl { color: #6b7280; }\n  .tombol-cancel { margin-top: 10px; width: 100%; padding: 11px; border: none; border-radius: 9px; background: #dc2626; color: #fff; font-size: 0.95rem; font-weight: 700; cursor: pointer; }\n  .tombol-cancel:disabled { background: #fca5a5; cursor: default; }\n  .kosong, .memuat, .galat { text-align: center; padding: 30px 12px; color: #6b7280; background: #fff; border: 1px dashed #d1d5db; border-radius: 12px; }\n  .galat { color: #991b1b; border-color: #fecaca; background: #fef2f2; }\n  .modal { position: fixed; inset: 0; background: rgba(15,23,42,0.6); display: none; align-items: center; justify-content: center; z-index: 9999; padding: 16px; }\n  .modal.tampil { display: flex; }\n  .modal-kotak { background: #fff; border-radius: 14px; width: 100%; max-width: 460px; padding: 20px; box-shadow: 0 12px 40px rgba(0,0,0,0.3); }\n  .modal-kotak h3 { margin: 0 0 8px; font-size: 1.1rem; }\n  .modal-kotak p { margin: 0 0 12px; color: #4b5563; font-size: 0.9rem; line-height: 1.5; }\n  .modal-kotak textarea { width: 100%; box-sizing: border-box; min-height: 90px; padding: 10px; border: 1px solid #d1d5db; border-radius: 8px; font-size: 0.95rem; font-family: inherit; }\n  .modal-galat { color: #b91c1c; font-size: 0.88rem; margin-top: 8px; display: none; }\n  .modal-tombol { display: flex; gap: 10px; margin-top: 14px; }\n  .modal-tombol button { flex: 1; padding: 11px; border-radius: 9px; border: none; font-size: 0.95rem; font-weight: 700; cursor: pointer; }\n  .btn-kembali { background: #f3f4f6; color: #374151; }\n  .btn-ya { background: #dc2626; color: #fff; }\n  .btn-ya:disabled { background: #fca5a5; cursor: default; }\n  .toast { position: fixed; left: 50%; bottom: 24px; transform: translateX(-50%); background: #111827; color: #fff; padding: 10px 18px; border-radius: 10px; font-size: 0.92rem; display: none; z-index: 10000; max-width: 90%; text-align: center; }\n  @media (max-width: 600px) { .navbar { padding: 0.8rem 1rem; } .container { padding: 1rem; } .page-title { font-size: 1.3rem; } }\n  </style>\n<script id=\"abadi-gas-shim\">\n(function() {\n  if (window.google && window.google.script && window.google.script.run) return;\n  function getQueryToken() {\n    try {\n      var p = new URLSearchParams(window.location.search);\n      return p.get('token') || '';\n    } catch (_) { return ''; }\n  }\n  function createRunner(successHandler, failureHandler, userObj) {\n    return new Proxy({}, {\n      get: function(target, prop) {\n        if (prop === 'withSuccessHandler') {\n          return function(fn) { return createRunner(fn, failureHandler, userObj); };\n        }\n        if (prop === 'withFailureHandler') {\n          return function(fn) { return createRunner(successHandler, fn, userObj); };\n        }\n        if (prop === 'withUserObject') {\n          return function(obj) { return createRunner(successHandler, failureHandler, obj); };\n        }\n        return function() {\n          var args = Array.prototype.slice.call(arguments);\n          var tok = window.__PAGE_TOKEN__ || (typeof PAGE_TOKEN !== 'undefined' ? PAGE_TOKEN : '') || getQueryToken();\n          var payload = {\n            token: tok,\n            action: prop,\n            data: args[0] !== undefined ? args[0] : null,\n            args: args\n          };\n          fetch('/api/web', {\n            method: 'POST',\n            headers: { 'Content-Type': 'application/json' },\n            body: JSON.stringify(payload)\n          })\n          .then(function(res) {\n            return res.text().then(function(text) {\n              var json = null;\n              try { json = JSON.parse(text); } catch(_) {}\n              if (!res.ok) {\n                var errMsg = (json && json.error && (json.error.message || json.error)) || ('HTTP ' + res.status + ': ' + text);\n                var err = new Error(errMsg);\n                if (failureHandler) failureHandler(err, userObj);\n                else alert('Galat server: ' + errMsg);\n                return;\n              }\n              if (json) {\n                if (successHandler) successHandler(json, userObj);\n              } else {\n                if (successHandler) successHandler(text, userObj);\n              }\n            });\n          })\n          .catch(function(err) {\n            if (failureHandler) failureHandler(err, userObj);\n            else alert('Sambungan terputus: ' + (err.message || err));\n          });\n        };\n      }\n    });\n  }\n  window.google = { script: { run: createRunner(null, null, null) } };\n  // Event delegation untuk menjaga ?token= pada semua navigasi internal /web\n  document.addEventListener('click', function(e) {\n    var a = e.target && e.target.closest('a');\n    if (a && a.href && a.origin === window.location.origin && a.pathname.startsWith('/web')) {\n      var u = new URL(a.href);\n      var tok = window.__PAGE_TOKEN__ || (typeof PAGE_TOKEN !== 'undefined' ? PAGE_TOKEN : '') || getQueryToken();\n      if (tok && !u.searchParams.has('token')) {\n        u.searchParams.set('token', tok);\n        a.href = u.toString();\n      }\n    }\n  }, true);\n})();\n</script>\n</head>\n<body>\n<script>\nvar PAGE_TOKEN='";
