const PAGE_RENDERERS = {
  'approval': render_approval,
  'cancelwo': render_cancelwo,
  'main': render_main,
  'mechanicdashboard': render_mechanicdashboard,
  'reports': render_reports,
  'workorder': render_workorder,
  'dashboard': render_main,
  'create': render_workorder,
  'mechanic': render_mechanicdashboard,
  'monitoring': render_mechanicdashboard,
  'approvals': render_approval,
  'cancel': render_cancelwo,
};

export function renderWebPage(pageName, ctx) {
  const norm = String(pageName || '').toLowerCase().trim();
  const renderer = PAGE_RENDERERS[norm];
  if (!renderer) {
    // Default fallback
    const fallback = PAGE_RENDERERS['main'] || PAGE_RENDERERS['dashboard'] || Object.values(PAGE_RENDERERS)[0];
    if (fallback) return fallback(ctx);
    return '<!DOCTYPE html><html><body><h1>Halaman tidak ditemukan: ' + norm + '</h1></body></html>';
  }
  return renderer(ctx);
}
